INSERT INTO feature VALUES('run-targets','runtime','Run targets','running-programs','declined','ordinary',NULL,'Retired by #2572: a source''s final expression no longer runs. Every expression the parser did not repair is refused where it stands at a source''s top level, `OutOfFragment.TopLevel`, the last one too, and `gandr run` runs the `main` a source declares (run-entry), refusing a source that declares none.',NULL,NULL,NULL,'#2572 #2846');
